    --np-u-lock: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M6 11h12v9H6zM8.5 11V8a3.5 3.5 0 0 1 7 0v3'/></svg>");
