:is(#left-nav-panel, #right-nav-panel, #np_menu) :is(.fa-check)::before { --np-ico: var(--np-u-check); }
:is(#left-nav-panel, #right-nav-panel, #np_menu) :is(.fa-ellipsis)::before { --np-ico: var(--np-u-more); }
:is(#left-nav-panel, #right-nav-panel, #np_menu) :is(.fa-images, .fa-image)::before { --np-ico: var(--np-u-image); }
:is(#left-nav-panel, #right-nav-panel, #np_menu) :is(.fa-circle-dot)::before { --np-ico: var(--np-u-dot); }
/* ==== end themes/nowplaying/icons-ui.css ==== */

/* ---------------- 顶栏 ---------------- */
#top-bar {
    background: var(--np-base);
    box-shadow: none;
    backdrop-filter: none;
}

#top-settings-holder .drawer-icon {
    color: var(--np-sub);
    opacity: 1;
    position: relative;
    transition: color .2s, transform .15s var(--np-ease);
}

#top-settings-holder .drawer-icon:hover {
    color: var(--np-text);
}

#top-settings-holder .drawer-icon:active {
    transform: scale(.92);
}

#top-settings-holder .drawer-icon.openIcon {
    color: var(--np-text);
}

/* 打开的那个图标下面一个小点（播放器里「正在用」的记号） */
#top-settings-holder .drawer-icon::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -7px;
    width: 4px;
    height: 4px;
    margin-left: -2px;
    border-radius: 50%;
    background: var(--np-accent);
    transform: scale(0);
    transition: transform .25s var(--np-ease);
}

#top-settings-holder .drawer-icon.openIcon::after {
    transform: scale(1);
}

/* ---------------- 聊天面板 ---------------- */
#sheld {
    background: var(--np-panel);
    border-radius: 8px;
    overflow: hidden;
}

#chat {
    background:
        linear-gradient(to bottom,
            var(--np-art) 0,
            color-mix(in srgb, var(--np-art) 45%, var(--np-panel)) 300px,
            var(--np-panel) 560px) var(--np-panel);
    background-attachment: local;
    padding: 0 var(--np-pad) 32px;
    gap: 2px;
}

/* 专辑头：封面 + 「角色」+ 大名字 + 一行小字 */
#np_hero {
    display: flex;
    align-items: flex-end;
    gap: 24px;
    padding: 64px 0 24px;
    color: var(--np-on-art);
    flex-shrink: 0;
    align-self: stretch;
}

#np_hero .np-cover {
    width: clamp(140px, 14vw, 220px);
    aspect-ratio: 1;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 4px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, .5);
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_hero .np-info {
    min-width: 0;
}

#np_hero .np-kicker {
    font-size: 14px;
    font-weight: 500;
}

#np_hero .np-title {
    font-size: clamp(40px, 5vw, 92px);
    font-weight: 900;
    line-height: 1.02;
    letter-spacing: -.03em;
    margin: 4px 0 14px;
    overflow-wrap: anywhere;
}

#np_hero .np-meta {
    font-size: 14px;
    opacity: .82;
}

#np_hero .np-meta b {
    font-weight: 700;
    opacity: 1;
}

/* 专辑头下面那排：大圆按钮 = 继续写 */
#np_actions {
    display: flex;
    align-items: center;
    gap: 24px;
    padding: 8px 0 24px;
    flex-shrink: 0;
}

.np-play {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: var(--np-accent);
    color: var(--np-on-accent);
    font-size: 22px;
    cursor: pointer;
    transition: transform .15s var(--np-ease), filter .15s;
}

.np-play:hover {
    transform: scale(1.05);
    filter: brightness(1.08);
}

.np-play:active {
    transform: scale(.95);
}

.np-play i {
    margin-left: 3px;
}

#np_actions .np-hint {
    color: var(--np-sub);
    font-size: 14px;
}

/* 往下滚以后，顶上一条细栏：封面色 + 小播放钮 + 名字 */
#np_top {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 64px;
    z-index: 35;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 var(--np-pad);
    background: color-mix(in srgb, var(--np-art) 70%, #000);
    color: var(--np-on-art);
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -.01em;
    opacity: 0;
    pointer-events: none;
    transition: opacity .25s;
}

#np_top .np-play {
    width: 40px;
    height: 40px;
    font-size: 15px;
}

html.np-scrolled #np_top {
    opacity: 1;
    pointer-events: auto;
}

/* ---------------- 消息 = 曲目 ---------------- */
#chat .mes {
    position: relative;
    padding: 12px 14px 14px 56px;
    border-radius: 6px;
    background: none;
    transition: background-color .2s;
}

#chat .mes:hover {
    background: var(--np-hover);
}

/* 序号（消息编号）；最新的回复是「正在播放」，序号变成强调色 */
#chat .mes::before {
    content: attr(mesid);
    position: absolute;
    left: 6px;
    top: 26px;
    width: 32px;
    text-align: right;
    font: 500 14px/1 var(--np-font);
    font-variant-numeric: tabular-nums;
    color: var(--np-sub);
}

#chat .mes.last_mes[is_user="false"]::before {
    color: var(--np-accent);
}

/* 生成中：序号换成三根跳动的音柱 */
@keyframes np-b1 { 0%, 100% { --np-b1: 25%; } 50% { --np-b1: 100%; } }
@keyframes np-b2 { 0%, 100% { --np-b2: 90%; } 50% { --np-b2: 30%; } }
@keyframes np-b3 { 0%, 100% { --np-b3: 45%; } 50% { --np-b3: 95%; } }

body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
    content: '';
    left: 24px;
    top: 24px;
    width: 14px;
    height: 14px;
    background:
        linear-gradient(var(--np-accent), var(--np-accent)) 0 100% / 3px var(--np-b1) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 50% 100% / 3px var(--np-b2) no-repeat,
        linear-gradient(var(--np-accent), var(--np-accent)) 100% 100% / 3px var(--np-b3) no-repeat;
    animation: np-b1 .8s ease-in-out infinite, np-b2 .65s ease-in-out infinite, np-b3 1s ease-in-out infinite;
}

#chat .mes .mesAvatarWrapper {
    position: static;
}

#chat .mes .avatar {
    width: 44px;
    height: 44px;
    margin-right: 14px;
}

body #chat .mes .avatar img {
    width: 44px;
    height: 44px;
    border-radius: 4px !important;
    object-fit: cover;
    object-position: 50% 18%;
}

#chat .mes .ch_name .name_text {
    font-size: 16px;
    font-weight: 700;
    color: var(--np-text);
    transition: color .3s;
}

#chat .mes.last_mes[is_user="false"] .ch_name .name_text {
    color: var(--np-accent);
}

#chat .mes .timestamp {
    color: var(--np-sub);
    font-size: 13px;
    opacity: 1;
}

/* 消息按钮：悬停那一行才出现 */
#chat .mes .mes_button {
    opacity: .75;
    color: var(--np-sub);
}

#chat .mes .mes_button:hover {
    opacity: 1;
    color: var(--np-text);
}

@media (hover: hover) {
    #chat .mes .mes_buttons {
        opacity: 0;
        transition: opacity .15s;
    }

    #chat .mes:hover .mes_buttons,
    #chat .mes:focus-within .mes_buttons {
        opacity: 1;
    }
}

/* 正文 */
#chat .mes_text {
    font-size: var(--np-prose-size);
    line-height: var(--np-prose-leading);
    font-weight: 400;
    color: var(--np-text);
    padding-right: 8px;
}

/* 对白比正文亮一级、稍粗；心理是灰的；代码是深一级的底 */
#chat .mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-weight: 500;
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--SmartThemeEmColor);
}

#chat .mes_text code {
    background: var(--np-elev);
    color: var(--np-text);
    border-radius: 4px;
    padding: .1em .35em;
    border: 0;
}

#chat .mes_text pre {
    background: var(--np-elev);
    border-radius: 8px;
    border: 0;
}

#chat .mes_text pre code {
    background: none;
    padding: 1em 1.2em;
    line-height: 1.6;
    font-size: 14px;
}

#chat .mes_text blockquote {
    border-left: 3px solid var(--np-accent);
    background: var(--np-hover);
    border-radius: 0 6px 6px 0;
}

/* 主题脚本把左右换版搬到了播放条上，消息里的就不画了 */
html.np-js #chat .mes .swipe_left,
html.np-js #chat .mes .swipe_right,
html.np-js #chat .mes .swipes-counter {
    display: none !important;
}

/* ---------------- 播放条 ---------------- */
#form_sheld {
    position: relative;
}

#send_form {
    background: transparent;
    border: 0;
    border-radius: 0;
    backdrop-filter: none;
}

#nonQRFormItems {
    align-items: center;
    column-gap: 10px;
}

#leftSendForm {
    order: 1;
}

#send_textarea {
    order: 2;
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 22px;
    padding: 11px 18px;
    min-height: 44px;
    font-size: 15px;
    color: var(--np-text);
    transition: background-color .2s, border-color .2s;
}

#send_textarea:hover {
    background: var(--np-elev-hi);
}

/* 酒馆一打开就把光标放进输入框，所以焦点框只淡淡一圈 */
#send_textarea:focus-visible {
    border-color: color-mix(in srgb, var(--np-text) 22%, transparent);
    outline: none;
}

#send_form:has(#send_textarea:focus-visible) {
    border: 0;
    outline: none;
}

#rightSendForm {
    order: 3;
    flex-wrap: nowrap;
    align-items: center;
    gap: 4px;
}

#leftSendForm > div,
#rightSendForm > div {
    color: var(--np-sub);
    opacity: 1;
    transition: color .15s, transform .15s var(--np-ease);
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--np-text);
}

#leftSendForm > div:active,
#rightSendForm > div:active {
    transform: scale(.9);
}

/* 控制钮的顺序：重新生成 · 上一版 · 发送 · 下一版 · 继续 · 代写 */
#np_regen { order: 1; }
#np_prev { order: 2; }
#rightSendForm > #send_but,
#rightSendForm > #mes_stop { order: 3; }
#np_next { order: 4; }
#mes_continue { order: 5; }
#mes_impersonate { order: 6; }
#rightSendForm > div:not(.np-ctl, #send_but, #mes_stop, #mes_continue, #mes_impersonate) { order: 7; }

.np-ctl {
    width: 32px;
    height: 32px;
    display: grid;
    place-items: center;
    font-size: 16px;
    cursor: pointer;
}

.np-ctl.np-off {
    opacity: .35 !important;
    pointer-events: none;
}

/* 发送 = 白色圆形的播放钮；生成中变成暂停（停止） */
#rightSendForm > #send_but,
#rightSendForm > #mes_stop {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    align-items: center;
    justify-content: center;
    background: var(--np-text);
    color: var(--np-base);
    font-size: 16px;
    margin: 0 6px;
}

#rightSendForm > #send_but:hover,
#rightSendForm > #mes_stop:hover {
    color: var(--np-base);
    transform: scale(1.06);
}

#rightSendForm > #send_but:active,
#rightSendForm > #mes_stop:active {
    transform: scale(.94);
}

#send_but::before {
    content: '\f04b';
    margin-left: 2px;
}

/* 停止钮里酒馆自己的图标不要，换成暂停 */
#mes_stop > * {
    display: none !important;
}

#mes_stop::before {
    content: '\f04c';
    font: var(--fa-font-solid);
}

/* 播放条顶边一条进度线；生成中有一段亮光来回走 */
@keyframes np-sweep {
    from { background-position: -40% 0; }
    to { background-position: 140% 0; }
}

#form_sheld::before {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    height: 2px;
    background: var(--np-line);
}

body[data-generating="true"] #form_sheld::before {
    background:
        linear-gradient(90deg, transparent, var(--np-accent), transparent) -40% 0 / 40% 100% no-repeat,
        var(--np-line);
    animation: np-sweep 1.4s linear infinite;
}

/* 播放条左边：正在播放的角色 */
#np_now {
    order: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
    white-space: normal;
}

#np_now img {
    width: 56px;
    height: 56px;
    border-radius: 4px;
    object-fit: cover;
    object-position: 50% 18%;
    flex-shrink: 0;
    background: var(--np-elev);
}

#np_now .np-n {
    font-size: 14px;
    font-weight: 600;
    color: var(--np-text);
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#np_now .np-s {
    font-size: 12px;
    color: var(--np-sub);
    line-height: 1.4;
    white-space: nowrap;
}

/* ==== themes/nowplaying/layout.css ==== */
/* ================================================================
 * 版面：酒馆的左右面板、电脑、手机
 * ================================================================ */

/* ---------------- 酒馆的左右面板 ---------------- */
#left-nav-panel,
#right-nav-panel {
    background: var(--np-panel);
    border: 0;
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* 通用的按钮、输入框：播放器式的胶囊和深一级的底 */
.menu_button {
    background: var(--np-elev);
    border: 0;
    border-radius: 999px;
    color: var(--np-text);
    opacity: 1;
    transition: background-color .15s, transform .15s var(--np-ease);
}

.menu_button:hover {
    background: var(--np-elev-hi);
}

.menu_button:active {
    transform: scale(.96);
}

.text_pole,
select.text_pole {
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 6px;
    color: var(--np-text);
}

.text_pole:focus-visible {
    border-color: color-mix(in srgb, var(--np-text) 50%, transparent);
    outline: none;
}

/* 面板标题（右边是当前角色名） */
#rm_button_selected_ch h2 {
    font: 800 18px/1.3 var(--np-font);
    color: var(--np-text);
    letter-spacing: -.01em;
}

/* 资料库：角色列表一行一行，方形小封面 + 名字 + 一行灰字 */
#rm_print_characters_block .entity_block {
    padding: 8px;
    border-radius: 6px;
    align-items: center;
    gap: 12px;
    transition: background-color .15s;
}

#rm_print_characters_block .entity_block:hover {
    background: var(--np-hover);
}

#rm_print_characters_block .entity_block.np-cur {
    background: var(--np-elev);
}

body #rm_print_characters_block .avatar,
body #rm_print_characters_block .avatar img {
    width: 48px;
    height: 48px;
    border-radius: 4px !important;
    object-fit: cover;
    object-position: 50% 18%;
}

#rm_print_characters_block .ch_name {
    font-size: 15px;
    font-weight: 500;
    color: var(--np-text);
}

#rm_print_characters_block .np-cur .ch_name {
    color: var(--np-accent);
}

/* 每行只留名字和一行副标题「角色 · 6 天前」（主题脚本写进 data-np-sub）；简介、标签、版本号收起来 */
.np-js #rm_print_characters_block :is(.ch_description, .tags_inline, .character_version, .ch_add_placeholder, .ch_avatar_url) {
    display: none !important;
}

#rm_print_characters_block [data-np-sub]::after {
    content: attr(data-np-sub);
    display: block;
    width: 100%;
    font-size: 13px;
    color: var(--np-sub);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

#rm_print_characters_block .character_name_block {
    display: flex;
    align-items: center;
    gap: 6px;
}

#rm_print_characters_block .ch_name {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* 收藏的角色：酒馆默认金框金字，换成名字后一颗绿星（像「已加入喜欢」） */
body #rm_print_characters_block .is_fav .avatar {
    outline: none;
}

#rm_print_characters_block .is_fav .ch_name {
    color: var(--np-text);
}

#rm_print_characters_block .is_fav .character_name_block::after,
#rm_print_characters_block .np-cur .character_name_block::after {
    content: '';
    flex: none;
    width: 12px;
    height: 12px;
    background: var(--np-accent);
    -webkit-mask: var(--np-u-star-on) center / contain no-repeat;
    mask: var(--np-u-star-on) center / contain no-repeat;
}

/* 正在聊的那个：行尾一个小喇叭 */
#rm_print_characters_block .np-cur .character_name_block::after {
    width: 16px;
    height: 16px;
    margin-left: auto;
    -webkit-mask-image: var(--np-u-volume);
    mask-image: var(--np-u-volume);
}

#rm_print_characters_block .ch_fav_icon {
    display: none !important;
}

/* 列表上面的筛选：做成播放器资料库那种文字胶囊（收藏 / 群聊 / 文件夹 / 标签） */
#rm_characters_block .rm_tag_controls,
#rm_characters_block .rm_tag_filter {
    flex: 1 1 100%;
    gap: 8px;
    flex-wrap: wrap;
}

#rm_characters_block .rm_tag_filter .tag.actionable {
    display: inline-flex;
    flex: none;
    width: auto !important;
    min-width: 0;
    aspect-ratio: auto;
    white-space: nowrap;
    align-items: center;
    gap: 6px;
    height: 32px;
    padding: 0 12px;
    border: 0;
    border-radius: 999px;
    background: var(--np-elev) !important;
    color: var(--np-text) !important;
    font-size: 13px;
    opacity: 1;
    filter: none;
    transition: background-color .15s, color .15s;
}

#rm_characters_block .rm_tag_filter .tag.actionable:hover {
    background: var(--np-elev-hi) !important;
}

#rm_characters_block .rm_tag_filter .tag.actionable.selected {
    background: var(--np-accent) !important;
    color: var(--np-on-accent) !important;
}

#rm_characters_block .rm_tag_filter .tag.actionable.excluded {
    text-decoration: line-through;
    color: var(--np-sub) !important;
}

/* 文字胶囊只留字（像播放器的「歌单 / 艺人」），图标收起来 */
#rm_characters_block .rm_tag_filter :is(.filterByFavorites, .filterByGroups, .filterByFolder, .showTagList) .tag_name {
    display: none;
}

#rm_characters_block .rm_tag_filter .tag.actionable .tag_name {
    font-size: 15px;
}

#rm_characters_block .rm_tag_filter .tag.actionable::after {
    font-weight: 500;
}

#rm_characters_block .rm_tag_filter .filterByFavorites::after { content: '收藏'; }
#rm_characters_block .rm_tag_filter .filterByGroups::after { content: '群聊'; }
#rm_characters_block .rm_tag_filter .filterByFolder::after { content: '文件夹'; }
#rm_characters_block .rm_tag_filter .showTagList::after { content: '标签'; }

/* 标签管理、清除筛选：只留图标，不要底 */
#rm_characters_block .rm_tag_filter :is(.manageTags, .clearAllFilters).tag.actionable {
    background: transparent !important;
    color: var(--np-sub) !important;
    padding: 0 6px;
}

#rm_characters_block .rm_tag_filter :is(.manageTags, .clearAllFilters).tag.actionable:hover {
    color: var(--np-text) !important;
}

/* 分页那一行：小一号、灰 */
#rm_print_characters_pagination {
    color: var(--np-sub);
    font-size: 13px;
}

#rm_print_characters_pagination :is(.paginationjs-pages li, .paginationjs-pages li > a, select) {
    border-color: transparent !important;
    background-color: transparent;
}

#rm_print_characters_block .np-cur.is_fav .ch_name,
#rm_print_characters_block .np-cur .ch_name {
    color: var(--np-accent);
}

/* 关掉的世界书 / 预设条目：像播放列表里「暂不可播」的歌——整行变灰字，但不糊，标题照样读得清 */
.world_entry.disabledWIEntry {
    opacity: 1;
    filter: none;
}

.world_entry.disabledWIEntry .text_pole,
.world_entry.disabledWIEntry .world_entry_form_control,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--np-sub);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border-color: transparent;
}

/* 开着的条目：开关是绿的（像播放器的随机播放 / 循环键亮起） */
.world_entry .killSwitch.fa-toggle-on,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--np-accent);
    opacity: 1;
}

/* 滑块：细灰轨 + 白圆点，悬停时圆点变绿 */
body input[type="range"] {
    height: 4px;
    background: color-mix(in srgb, var(--np-text) 28%, transparent);
}

body input[type="range"]:hover {
    filter: none;
}

body input[type="range"]::-webkit-slider-thumb {
    width: 12px;
    height: 12px;
    border: 0;
    background: var(--np-text);
    box-shadow: 0 2px 4px rgba(0, 0, 0, .5);
    transition: transform .15s var(--np-ease), background-color .15s;
}

body input[type="range"]:hover::-webkit-slider-thumb,
body input[type="range"]:focus-visible::-webkit-slider-thumb {
    background: var(--np-accent);
    transform: scale(1.2);
}

body input[type="range"]::-moz-range-thumb {
    width: 12px;
    height: 12px;
    border: 0;
    background: var(--np-text);
}


/* ---------------- 右边面板的标题栏（主题脚本画的 #np_rhead） ----------------
 * 资料库 / 正在播放 / 编辑设定 三种页面用它；新建角色、群聊这些页面还用酒馆自己的 */
#np_rhead {
    display: none;
    align-items: center;
    gap: 10px;
    padding: 8px 8px 10px;
    color: var(--np-text);
}

.np-js #right-nav-panel:is([data-menu-type="characters"], [data-menu-type="character_edit"]) #np_rhead {
    display: flex;
}

.np-js #right-nav-panel:is([data-menu-type="characters"], [data-menu-type="character_edit"]) :is(#CharListButtonAndHotSwaps, #rm_PinAndTabs) {
    display: none !important;
}

.np-rh-title {
    flex: 1;
    min-width: 0;
    font: 700 16px/1.3 var(--np-font);
}

.np-rh-back,
.np-rh-pin {
    width: 32px;
    height: 32px;
    flex: none;
    border-radius: 50%;
    color: var(--np-sub);
    cursor: pointer;
    transition: color .15s, background-color .15s;
}

.np-rh-back::before,
.np-rh-pin::before {
    content: '';
    display: block;
    width: 100%;
    height: 100%;
    background: currentColor;
    -webkit-mask: var(--np-ico) center / 22px no-repeat;
    mask: var(--np-ico) center / 22px no-repeat;
}

.np-rh-back:hover,
.np-rh-pin:hover {
    color: var(--np-text);
}

/* 资料库页：左边是资料库图标（不可点）；展示页：资料库图标可点，回到列表；编辑页：返回箭头 */
#np_rhead .np-rh-back { --np-ico: var(--np-i-library); }
#np_rhead[data-mode="lib"] .np-rh-back { pointer-events: none; color: var(--np-text); }
#np_rhead[data-mode="edit"] .np-rh-back { --np-ico: var(--np-u-back); }
#np_rhead .np-rh-pin { --np-ico: var(--np-u-unlock); }
#np_rhead .np-rh-pin.np-on { --np-ico: var(--np-u-lock); color: var(--np-accent); }

#np_rhead .np-rh-done {
    display: none;
    white-space: nowrap;
    flex: none;
    padding: 6px 16px;
    font-weight: 700;
    background: var(--np-text);
    color: var(--np-base);
}

#np_rhead[data-mode="edit"] .np-rh-done { display: block; }

/* ---------------- 正在播放：展示页（#np_about） ---------------- */
#rm_ch_create_block {
    background: linear-gradient(to bottom, var(--np-art), color-mix(in srgb, var(--np-art) 25%, var(--np-panel)) 360px, var(--np-panel) 520px);
    border-radius: 8px;
    padding: 16px;
}

#np_about {
    display: none;
    flex-direction: column;
    color: var(--np-text);
}

.np-js #right-nav-panel[data-menu-type="character_edit"] #np_about:not([hidden]) {
    display: flex;
}

/* 展示页时，酒馆的编辑表单收起来；点「编辑」（html.np-editing）才露出来 */
.np-js:not(.np-editing) #right-nav-panel[data-menu-type="character_edit"]:has(#np_about:not([hidden])) #form_create {
    display: none;
}

.np-editing #np_about {
    display: none !important;
}

#np_about .np-big {
    width: 100%;
    aspect-ratio: 1;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 8px;
    background: var(--np-elev);
    box-shadow: 0 8px 32px rgba(0, 0, 0, .45);
}

#np_about .np-name {
    font: 800 26px/1.2 var(--np-font);
    letter-spacing: -.01em;
    margin-top: 20px;
    overflow-wrap: anywhere;
    color: var(--np-on-art);
}

#np_about .np-by {
    margin-top: 4px;
    font-size: 14px;
    color: color-mix(in srgb, var(--np-on-art) 72%, transparent);
}

#np_about .np-acts {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 14px 0 0 -6px;
}

#np_about .np-act {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    color: color-mix(in srgb, var(--np-on-art) 72%, transparent);
    cursor: pointer;
    transition: color .15s, transform .15s var(--np-ease);
}

#np_about .np-act::before {
    content: '';
    display: block;
    width: 100%;
    height: 100%;
    background: currentColor;
    -webkit-mask: var(--np-ico) center / 26px no-repeat;
    mask: var(--np-ico) center / 26px no-repeat;
}

#np_about .np-act:hover {
    color: var(--np-on-art);
    transform: scale(1.06);
}

#np_about .np-act:active {
    transform: scale(.94);
}

#np_about .np-fav { --np-ico: var(--np-u-star); }
#np_about .np-fav.np-on { --np-ico: var(--np-u-star-on); color: var(--np-accent); }
#np_about .np-edit { --np-ico: var(--np-u-pencil); }
#np_about .np-world { --np-ico: var(--np-u-globe); }
#np_about .np-chatlore { --np-ico: var(--np-u-chatBook); }
#np_about :is(.np-world, .np-chatlore).np-on { color: var(--np-accent); }
#np_about .np-act[hidden] { display: none; }
#np_about .np-more { --np-ico: var(--np-i-more); }

#np_about .np-card {
    margin-top: 20px;
    border-radius: 8px;
    background: var(--np-elev);
    overflow: hidden;
    cursor: pointer;
}

#np_about .np-card-img {
    height: 96px;
    padding: 16px;
    background: linear-gradient(to bottom, transparent, var(--np-elev)), var(--np-art);
    font-weight: 700;
    font-size: 15px;
    color: var(--np-on-art);
}

#np_about .np-card-stat {
    padding: 0 16px;
    font-size: 15px;
    font-weight: 600;
}

#np_about .np-card-body {
    padding: 8px 16px 16px;
    font-size: 14px;
    line-height: 1.65;
    color: var(--np-sub);
    white-space: pre-line;
    display: -webkit-box;
    -webkit-line-clamp: 6;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

#np_about .np-card-body.np-open {
    display: block;
}

/* ---------------- ⋯ 菜单（#np_menu） ---------------- */
#np_menu {
    position: fixed;
    z-index: 10000;
    min-width: 220px;
    max-width: min(320px, calc(100vw - 16px));
    max-height: calc(100dvh - 16px);
    overflow-y: auto;
    padding: 4px;
    border-radius: 6px;
    background: var(--np-elev-hi);
    color: var(--np-text);
    box-shadow: 0 16px 24px rgba(0, 0, 0, .3), 0 6px 8px rgba(0, 0, 0, .2);
    font-size: 14px;
}

#np_menu .np-mi {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    border-radius: 3px;
    cursor: pointer;
    color: color-mix(in srgb, var(--np-text) 90%, transparent);
}

#np_menu .np-mi:hover,
#np_menu .np-mi:focus-visible {
    background: rgba(255, 255, 255, .1);
    color: var(--np-text);
    outline: none;
}

#np_menu .np-mi i {
    font-size: 16px;
    color: var(--np-sub);
}

#np_menu .np-danger,
#np_menu .np-danger i {
    color: #ff7a7a;
}

#np_menu hr {
    border: 0;
    border-top: 1px solid rgba(255, 255, 255, .1);
    margin: 4px 0;
}

/* ---------------- 编辑设定 / 新建角色：酒馆的表单，头像缩成小封面 ---------------- */
#avatar-and-name-block,
#avatar-and-name-block > .expander {
    flex: none;
    min-width: 0;
    width: 100%;
    flex-wrap: nowrap;
    height: auto !important;
}

#avatar_div {
    min-width: 0;
    max-width: 100%;
    align-items: flex-start;
    gap: 14px;
}

body #rm_ch_create_block #avatar_div_div.avatar {
    width: 96px;
    height: 96px;
    flex: none;
    border-radius: 6px !important;
    overflow: hidden;
    box-shadow: 0 4px 16px rgba(0, 0, 0, .4);
}

body #rm_ch_create_block #avatar_load_preview {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    object-fit: cover;
    object-position: 50% 18%;
    border-radius: 6px !important;
}

#character_name_pole {
    font: 800 22px/1.2 var(--np-font);
    letter-spacing: -.01em;
    background: transparent;
    border-color: transparent;
    padding: 2px 0;
    color: var(--np-on-art);
}

#character_name_pole:hover,
#character_name_pole:focus-visible {
    background: rgba(0, 0, 0, .25);
    padding-inline: 6px;
}

#avatar_controls {
    flex: 1;
    min-width: 0;
    height: auto !important;
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
}

/* 已有角色的名字框被酒馆藏起来了，名字由主题脚本写进 --np-name */
#right-nav-panel[data-menu-type="character_edit"] #avatar_controls::before {
    content: var(--np-name, '');
    font: 800 20px/1.25 var(--np-font);
    color: var(--np-on-art);
    overflow-wrap: anywhere;
}

#avatar_controls .form_create_bottom_buttons_block {
    width: auto;
    max-width: 100%;
    height: auto;
    flex-wrap: wrap;
    align-content: flex-start;
    justify-content: flex-start;
    gap: 0;
}

#avatar_controls > label.flex1 {
    flex: none;
    height: auto;
}

#avatar_controls #char-management-dropdown {
    width: auto;
    max-width: 100%;
    margin: 0;
    border-radius: 500px;
    padding-inline: 14px 28px;
    background-color: rgba(0, 0, 0, .3);
}

/* 酒馆的「醒目标题条」（预设名、创作者的注释）：去掉白色高光渐变，平铺深一级的底 */
.standoutHeader {
    background-image: none;
    background-color: var(--np-elev);
    border-color: transparent;
    border-radius: 6px;
}

.standoutHeader ~ .inline-drawer-content {
    border-color: transparent;
    background-color: color-mix(in srgb, var(--np-elev) 50%, transparent);
    border-radius: 6px;
}

/* 预设绑定连接的链子：开着是绿色，不要底 */
label[for="bind_preset_to_connection"] {
    background: transparent !important;
    color: var(--np-sub);
}

label[for="bind_preset_to_connection"]:has(input:checked) {
    color: var(--np-accent);
}

/* ---------------- 面板里只有图标的按钮：去掉灰底圆片，只留线条图标 ---------------- */
:is(#left-nav-panel, #right-nav-panel) :is(.menu_button, .right_menu_button)[class*="fa-"],
:is(#left-nav-panel, #right-nav-panel) .menu_button:has(> i[class*="fa-"]:only-child) {
    background: transparent;
    color: var(--np-sub);
    min-width: 32px;
    height: 32px;
    padding: 0;
    display: inline-grid;
    place-items: center;
    font-size: 17px;
    border-radius: 50%;
    opacity: 1;
    filter: none;
    transition: color .15s, background-color .15s, transform .15s var(--np-ease);
}

:is(#left-nav-panel, #right-nav-panel) :is(.menu_button, .right_menu_button)[class*="fa-"]:hover,
:is(#left-nav-panel, #right-nav-panel) .menu_button:has(> i[class*="fa-"]:only-child):hover {
    background: var(--np-hover);
    color: var(--np-text);
}

/* 但这些按钮会被酒馆用 display 开关，不能让上面的 inline-grid 盖过去 */
:is(#left-nav-panel, #right-nav-panel) :is(.menu_button, .right_menu_button)[class*="fa-"]:is(.displayNone, [style*="display: none"]) {
    display: none;
}

/* 删除这类红按钮：平时灰，悬停变红 */
:is(#left-nav-panel, #right-nav-panel) .menu_button.red_button {
    background: transparent;
}

:is(#left-nav-panel, #right-nav-panel) .menu_button.red_button:hover {
    color: #ff7a7a;
}

/* 收藏键：收藏了是绿色实心星 */
/* 酒馆用 !important 把收藏染金、已挂世界书染另一种绿；统一成主题的绿 */
#right-nav-panel .fav_on,
#right-nav-panel .world_set {
    color: var(--np-accent) !important;
}

#right-nav-panel #delete_button.red_button {
    background: transparent !important;
}

#right-nav-panel #favorite_button.fav_on::before {
    --np-ico: var(--np-u-star-on);
}

/* 折叠小节的箭头：去掉圆片 */
:is(#left-nav-panel, #right-nav-panel) .inline-drawer-icon {
    background: transparent;
    color: var(--np-sub);
    opacity: 1;
    font-size: 18px;
    border: 0;
    box-shadow: none;
}

/* 问号、提示：淡一点的灰 */
:is(#left-nav-panel, #right-nav-panel) :is(.fa-circle-question, .fa-circle-info) {
    color: var(--np-sub);
    opacity: 1;
}

/* 下面一段一段的设定 */
#rm_ch_create_block textarea {
    background: var(--np-elev);
    border: 1px solid transparent;
    border-radius: 8px;
    color: var(--np-text);
    line-height: 1.6;
}

/* ================================================================
 * 电脑
 * ================================================================ */
@media screen and (min-width: 1001px) {
    #top-bar {
        width: 100vw;
    }

    #sheld {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
    }

    #chat {
        max-height: none;
    }

    #form_sheld {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        width: auto;
        margin: 0;
        padding: 12px 16px;
        background: var(--np-base);
        z-index: 40;
    }

    #form_sheld::before {
        left: calc((100vw - var(--sheldWidth)) / 2);
        right: calc((100vw - var(--sheldWidth)) / 2);
        top: 2px;
        border-radius: 2px;
    }

    #np_now {
        width: max(240px, calc((100vw - var(--sheldWidth)) / 2 - 16px));
    }

    /* 酒馆的左右面板：留缝、圆角，底下给播放条让位 */
    .fillLeft,
    .fillRight {
        top: var(--topBarBlockSize);
        width: calc((100vw - var(--sheldWidth)) / 2 - 2 * var(--np-gap));
        border-radius: 8px;
    }

    .fillLeft {
        left: var(--np-gap);
    }

    .fillRight {
        right: var(--np-gap);
        left: auto;
    }

    .fillLeft.openDrawer,
    .fillRight.openDrawer {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-bar) - var(--np-gap));
    }
}

/* ================================================================
 * 手机：顶栏挪到底部当标签栏（图标 + 两个字），封面色一直铺到屏幕顶
 * ================================================================ */
@media screen and (max-width: 1000px) {
    /* 「单击滑块以手动输入值」浮在面板顶上，手机上会压住预设名那行 */
    #left-nav-panel > .scrollableInner {
        padding-top: 26px;
    }

    html:root {
        --topBarBlockSize: env(safe-area-inset-top, 0px);
        --np-tab: calc(54px + env(safe-area-inset-bottom, 0px));
    }

    #ai-config-button { --np-label: '预设'; }
    #sys-settings-button { --np-label: '连接'; }
    #advanced-formatting-button { --np-label: '格式'; }
    #WI-SP-button { --np-label: '世界书'; }
    #user-settings-button { --np-label: '设置'; }
    #backgrounds-button { --np-label: '背景'; }
    #extensions-settings-button { --np-label: '扩展'; }
    #persona-management-button { --np-label: '人设'; }
    #rightNavHolder { --np-label: '角色'; }

    /* 酒馆给 <html> 加了 translateZ(0)，fixed 的 bottom: 0 会对不上屏幕底，所以从顶上量 */
    #top-bar {
        top: calc(100dvh - var(--np-tab)) !important;
        bottom: auto;
        height: var(--np-tab);
        background: var(--np-base);
    }

    #top-settings-holder {
        position: fixed;
        top: calc(100dvh - var(--np-tab)) !important;
        bottom: auto;
        left: 0;
        width: 100vw;
        height: var(--np-tab);
        padding: 0 4px env(safe-area-inset-bottom, 0px);
        box-sizing: border-box;
        align-items: stretch;
    }

    #top-settings-holder > .drawer {
        flex: 1 1 0;
        min-width: 0;
    }

    #top-settings-holder .drawer-toggle {
        width: 100%;
        height: 100%;
        display: flex;
        align-items: stretch;
    }

    #top-settings-holder .drawer-icon {
        width: 100%;
        height: 100%;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 4px;
    }

    #top-settings-holder .drawer-icon::before {
        width: 22px;
        height: 22px;
    }

    /* 小点换成两个字的标签 */
    #top-settings-holder .drawer-icon::after {
        content: var(--np-label, '');
        position: static;
        width: auto;
        height: auto;
        margin: 0;
        background: none;
        border-radius: 0;
        transform: none;
        font: 500 10px/1 var(--np-font);
        white-space: nowrap;
    }

    #top-settings-holder .drawer-icon:active {
        transform: scale(.9);
    }

    /* 聊天区和各个面板：从屏幕顶到标签栏 */
    html body #sheld {
        top: var(--topBarBlockSize) !important;
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        border-radius: 0;
    }

    .drawer-content {
        top: var(--topBarBlockSize) !important;
        max-height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
        border: 0;
    }

    #left-nav-panel.openDrawer,
    #right-nav-panel.openDrawer {
        height: calc(100dvh - var(--topBarBlockSize) - var(--np-tab)) !important;
    }

    #rm_ch_create_block {
        border-radius: 0;
    }

    #chat {
        max-height: none;
        min-height: 0;
        padding: 0 var(--np-m-pad) 12px;
    }

    /* 专辑头：封面居中，名字靠左、不加小标签，绿钮在右边 */
    #np_hero {
        flex-direction: column;
        align-items: stretch;
        gap: 18px;
        padding: 28px 0 4px;
    }

    #np_hero .np-cover {
        width: 64%;
        max-width: 260px;
        align-self: center;
    }

    #np_hero .np-kicker {
        display: none;
    }

    #np_hero .np-title {
        font-size: 24px;
        font-weight: 800;
        letter-spacing: -.01em;
        margin: 0 0 6px;
    }

    #np_hero .np-meta {
        font-size: 13px;
    }

    #np_actions {
        align-self: stretch;
        padding: 4px 0 12px;
        gap: 12px;
    }

    #np_actions .np-hint {
        order: 1;
        font-size: 13px;
    }

    #np_actions .np-play {
        order: 2;
        margin-left: auto;
        width: 48px;
        height: 48px;
        font-size: 18px;
    }

    #np_top {
        padding: 0 var(--np-m-pad);
        font-size: 16px;
        height: 52px;
    }

    #np_top .np-play {
        width: 32px;
        height: 32px;
        font-size: 12px;
    }

    /* 消息：更紧凑 */
    #chat .mes {
        padding: 10px 4px 12px;
    }

    #chat .mes::before {
        content: none;
    }

    #chat .mes .avatar,
    body #chat .mes .avatar img {
        width: 34px;
        height: 34px;
    }

    #chat .mes .avatar {
        margin-right: 12px;
    }

    #chat .mes .ch_name .name_text {
        font-size: 14px;
    }

    #chat .mes .timestamp {
        font-size: 12px;
    }

    #chat .mes_text {
        font-size: calc(var(--np-prose-size) - 1px);
        line-height: 1.7;
    }

    #chat .mes .mes_button {
        font-size: 14px;
        opacity: .55;
    }

    /* 生成中：音柱挪到名字前面 */
    body[data-generating="true"] #chat .mes.last_mes[is_user="false"]::before {
        content: '';
        left: 50px;
        top: 13px;
        width: 12px;
        height: 12px;
    }

    body[data-generating="true"] #chat .mes.last_mes[is_user="false"] .ch_name .name_text {
        padding-left: 18px;
    }

    /* 迷你播放条：封面 · 输入框 · 菜单 · 扩展 · 发送 */
    #form_sheld {
        flex-shrink: 0;
        margin: 0 8px 8px;
        width: auto;
        border-radius: 8px;
        background: color-mix(in srgb, var(--np-art) 58%, #000);
        overflow: hidden;
        padding: 6px 8px 8px 6px;
    }

    #form_sheld::before {
        top: auto;
        bottom: 0;
        left: 8px;
        right: 8px;
        background: rgba(255, 255, 255, .22);
    }

    #nonQRFormItems {
        column-gap: 6px;
    }

    #np_now {
        width: auto;
    }

    #np_now img {
        width: 36px;
        height: 36px;
    }

    #np_now > div {
        display: none;
    }

    #send_textarea {
        background: transparent;
        border-color: transparent;
        color: var(--np-on-art);
        padding: 8px 4px;
        min-height: 36px;
        font-size: 15px;
        text-align: left;
        resize: none;
    }

    #send_textarea::placeholder {
        color: rgba(255, 255, 255, .7);
    }

    #send_textarea:hover,
    #send_textarea:focus-visible {
        background: transparent;
        border-color: transparent;
    }

    #leftSendForm {
        order: 3;
        width: auto;
        gap: 2px;
    }

    #rightSendForm {
        order: 4;
        width: auto;
    }

    #leftSendForm > div,
    #rightSendForm > div {
        color: rgba(255, 255, 255, .82);
    }

    #np_prev,
    #np_next,
    #np_regen,
    #mes_impersonate,
    #mes_continue {
        display: none !important;
    }

    #rightSendForm > #send_but,
    #rightSendForm > #mes_stop {
        width: 34px;
        height: 34px;
        margin: 0 0 0 4px;
        font-size: 13px;
        background: #fff;
        color: #000;
    }
}
/* ==== end themes/nowplaying/layout.css ==== */
/* ==== end themes/nowplaying/base.css ==== */
